// Logout.js (React Component)

import React from 'react';
import { useHistory } from 'react-router-dom'; // For navigating programmatically
import { logout } from './api'; // Import the logout function from api.js

const Logout = () => {
    const history = useHistory(); // Initialize the useHistory hook for navigation

    // Handle logout process
    const handleLogout = async () => {
        try {
            // Call the logout function from the api.js
            const message = await logout();
            console.log(message); // Optional: log the successful logout message to the console

            // Remove the JWT token from localStorage (or cookies)
            localStorage.removeItem('token'); // Remove token stored in localStorage

            // Redirect the user to the login page after successful logout
            history.push('/login'); // Use history.push to navigate to the login page
        } catch (error) {
            console.error('Logout failed:', error);
            alert('There was an error logging out. Please try again.');
        }
    };

    return (
        <div>
            <h1>You have been logged out</h1>
            <p>Click the button below to logout.</p>
            <button onClick={handleLogout}>Logout</button>
        </div>
    );
};

export default Logout;
